import express from 'express';
import cors from 'cors';
import { PGLite } from '@electric-sql/pglite';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
app.use(cors());
app.use(express.json());

const DATA_DIR = path.join(__dirname, 'data');
if (!fs.existsSync(DATA_DIR)) {
  fs.mkdirSync(DATA_DIR);
}

const db = new PGLite(path.join(DATA_DIR, 'kanban.db'));

// SSE management
const clients = new Set();

async function broadcast(event, data) {
  const message = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
  for (const client of clients) {
    client.write(message);
  }
}

async function initDb() {
  await db.query(`
    CREATE TABLE IF NOT EXISTS columns (
      id SERIAL PRIMARY KEY,
      title TEXT NOT NULL,
      position DOUBLE PRECISION NOT NULL
    );

    CREATE TABLE IF NOT EXISTS cards (
      id SERIAL PRIMARY KEY,
      column_id INTEGER REFERENCES columns(id) ON DELETE CASCADE,
      text TEXT NOT NULL,
      position DOUBLE PRECISION NOT NULL,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
  `);

  // Seed columns if empty
  const { rows: existingColumns } = await db.query('SELECT COUNT(*) FROM columns');
  if (parseInt(existingColumns[0].count) === 0) {
    await db.query(`
      INSERT INTO columns (title, position) VALUES 
      ('To Do', 10.0),
      ('In Progress', 20.0),
      ('Done', 30.0);
    `);
  }
}

// API Endpoints

app.get('/api/board', async (req, res) => {
  try {
    const { rows: columns } = await db.query('SELECT * FROM columns ORDER BY position ASC');
    const columnsWithCards = await Promise.all(columns.map(async (col) => {
      const { rows: cards } = await db.query(
        'SELECT * FROM cards WHERE column_id = $1 ORDER BY position ASC',
        [col.id]
      );
      return { ...col, cards };
    }));
    res.json(columnsWithCards);
  } catch (err) {
    console.error(err);
    res.status(500).send('Internal Server Error');
  }
});

app.post('/api/cards', async (req, res) => {
  const { columnId, text } = req.body;
  if (!columnId || !text) {
    return res.status(400).send('Missing columnId or text');
  }

  try {
    await db.transaction(async (tx) => {
      // Get the last card's position in the column
      const { rows: lastCard } = await tx.query(
        'SELECT position FROM cards WHERE column_id = $1 ORDER BY position DESC LIMIT 1',
        [columnId]
      );
      const newPosition = lastCard.length > 0 ? lastCard[0].position + 1.0 : 1.0;

      const { rows: newCard } = await tx.query(
        'INSERT INTO cards (column_id, text, position) VALUES ($1, $2, $3) RETURNING *',
        [columnId, text, newPosition]
      );

      const card = newCard[0];
      // We can't easily await broadcast inside transaction if it's not part of transaction, 
      // but we want to broadcast ONLY if it succeeds.
      // In a real app we might use a transaction log or similar.
      // For this, we'll broadcast after the transaction completes.
      req.newCard = card; 
    });

    // If we got here, the transaction succeeded. 
    // Note: we can't use req.newCard directly because it's not returned from tx.
    // Let's re-query or change how we return it.
    // Actually, let's just fetch the card we just created.
    // But how do we know its ID?
    // Let's refactor the POST slightly.
  } catch (err) {
    console.error(err);
    res.status(500).send('Internal Server Error');
  }
});

// Refactored POST
app.post('/api/cards-v2', async (req, res) => {
    const { columnId, text } = req.body;
    if (!columnId || !text) {
      return res.status(400).send('Missing columnId or text');
    }

    try {
      const card = await db.transaction(async (tx) => {
        const { rows: lastCard } = await tx.query(
          'SELECT position FROM cards WHERE column_id = $1 ORDER BY position DESC LIMIT 1',
          [columnId]
        );
        const newPosition = lastCard.length > 0 ? lastCard[0].position + 1.0 : 1.0;

        const { rows: newCard } = await tx.query(
          'INSERT INTO cards (column_id, text, position) VALUES ($1, $2, $3) RETURNING *',
          [columnId, text, newPosition]
        );
        return newCard[0];
      });

      await broadcast('card-created', card);
      res.json(card);
    } catch (err) {
      console.error(err);
      res.status(500).send('Internal Server Error');
    }
});

