async function renormalizeColumn(tx, columnId) {
  const { rows: cards } = await tx.query(
    'SELECT id FROM cards WHERE column_id = $1 ORDER BY position ASC',
    [columnId]
  );

  let currentPos = 10.0;
  for (const card of cards) {
    await tx.query(
      'UPDATE cards SET position = $1 WHERE id = $2',
      [currentPos, card.id]
    );
    currentPos += 10.0;
  }
}

