        const { rows: reFetchedCard } = await tx.query(
          'SELECT * FROM cards WHERE id = $1',
          [cardId]
        );
        return reFetchedCard[0];
      }

      return updatedCard[0];
    });

    await broadcast('card-moved', movedCard);
