  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');

  req.on('close', () => {
    clients.delete(res);
  });

  clients.add(res);
  // Send initial connection success if needed, but SSE usually just stays open.
  res.write(': ok\n\n');
});

const PORT = 3000;
app.listen(PORT, async () => {
  console.log(`Server running on port ${PORT}`);
  await initDb();
